async function open(edit=false){const router=createRouter({history:createMemoryHistory(),routes:[{path:'/rules/scenes/create',component:SceneEditorPage},{path:'/rules/scenes/:id/edit',component:SceneEditorPage},{path:'/rules/scenes/:id',component:defineComponent({template:'<div>场景详情</div>'})},{path:'/rules/scenes',component:defineComponent({template:'<div>场景目录</div>'})}]});await router.push(edit?`/rules/scenes/${scene}/edit`:'/rules/scenes/create');await router.isReady();wrapper=mount(RouterView,{global:{plugins:[router],stubs}});await flushPromises();return router}
function keep(body:SceneBody){latest={...latest,conditions:cloneSceneValue(body.conditions),actions:cloneSceneValue(body.actions),deviceScope:cloneSceneValue(body.deviceScope),executionPolicy:body.executionPolicy?{...body.executionPolicy}:null};remote={...remote,name:body.name,description:body.description,...(body.tags!==undefined?{tags:cloneSceneValue(body.tags)}:{})}}
function applyRevision(body:SceneBody,enabled?:boolean|null){
 const active=!!remote.activeVersionId;keep(body);latest={...latest,id:'10000000-0000-7000-8000-'+String(20+(++revisionSequence)).padStart(12,'0'),versionNumber:latest.versionNumber+1}
 remote={...remote,version:remote.version+(enabled==null?1:enabled?2:active?3:1),...(enabled==null?{}:{status:enabled?'ACTIVE':active?'PAUSED':'DRAFT',activeVersionId:enabled||active?latest.id:null})};return {...remote}
}
